class AdvancedBPETokenizer:
    def __init__(self, vocab_size: int = 100000):
        self.vocab = {}
        self.reverse_vocab = {}
        self.vocab_size = vocab_size
        self.bpe_merges = []
        self.word_splits = {}

        # GPT-4 szintű speciális tokenek
        self.special_tokens = {
            '<|endoftext|>': 0,
            '<|startoftext|>': 1,
            '<|unk|>': 2,
            '<|pad|>': 3,
            '<|system|>': 4,
            '<|user|>': 5,
            '<|assistant|>': 6,
            '<|function_call|>': 7,
            '<|function_result|>': 8,
            '<|image|>': 9,
            '<|code|>': 10,
            '<|math|>': 11,
            '<|reasoning|>': 12,
            '<|critique|>': 13,
            '<|summary|>': 14,
            '<|translation|>': 15
        }

        # Nyelvek és domain-specifikus tokenek
        self.language_tokens = {
            '<|hungarian|>': 16,
            '<|english|>': 17,
            '<|german|>': 18,
            '<|french|>': 19,
            '<|spanish|>': 20,
            '<|python|>': 21,
            '<|javascript|>': 22,
            '<|html|>': 23,
            '<|css|>': 24,
            '<|json|>': 25
        }

        self.special_tokens.update(self.language_tokens)

        print(f"🔤 AdvancedBPETokenizer inicializálva {len(self.special_tokens)} speciális tokennel")

    def build_vocab(self, texts: List[str]):
        """GPT-4 szintű BPE vocabulár építése byte-level encoding-gal"""
        print("🔧 Fejlett BPE vocabulár építése...")

        # Speciális tokenek hozzáadása
        self.vocab.update(self.special_tokens)
        current_id = len(self.special_tokens)

        # Byte-level karakterek (0-255)
        for i in range(256):
            byte_char = chr(i) if i < 128 else f"<{i}>"
            if byte_char not in self.vocab:
                self.vocab[byte_char] = current_id
                current_id += 1

        # Unicode karakterek gyakori nyelvekhez
        unicode_chars = set()
        for text in texts:
            for char in text:
                if ord(char) > 255:
                    unicode_chars.add(char)

        for char in sorted(unicode_chars):
            if char not in self.vocab:
                self.vocab[char] = current_id
                current_id += 1

        # Fejlett BPE merge folyamat
        word_freq = self._get_advanced_word_frequencies(texts)

        merge_iterations = min(50000, self.vocab_size - len(self.vocab))
        print(f"🔄 {merge_iterations} BPE merge iteráció...")

        for i in range(merge_iterations):
            if i % 5000 == 0:
                print(f"  📊 BPE iteráció: {i}/{merge_iterations}")

            pairs = self._get_pairs_frequencies(word_freq)
            if not pairs:
                break

            # Legjobb pár kiválasztása entrópia alapján
            best_pair = self._select_best_pair(pairs, word_freq)
            if best_pair is None:
                break

            self._merge_pair(best_pair, word_freq)

            # Új token hozzáadása
            new_token = best_pair[0] + best_pair[1]
            if new_token not in self.vocab and len(new_token) <= 20:
                self.vocab[new_token] = current_id
                current_id += 1
                self.bpe_merges.append(best_pair)

        self.reverse_vocab = {v: k for k, v in self.vocab.items()}
        print(f"✅ Fejlett BPE vocabulár kész: {len(self.vocab)} token")
        print(f"🔑 Sándor Kollár - GPT-4 szintű tokenizáció implementálva")

    def _get_advanced_word_frequencies(self, texts: List[str]) -> Dict[str, int]:
        """Fejlett szógyakoriság számítás többnyelvű támogatással"""
        word_freq = {}

        for text in texts:
            # Regex alapú tokenizáció
            words = re.findall(r'\w+|[^\w\s]', text.lower())

            for word in words:
                # Byte-level reprezentáció
                word_bytes = word.encode('utf-8', errors='ignore').decode('utf-8')
                word_chars = ' '.join(word_bytes) + ' </w>'
                word_freq[word_chars] = word_freq.get(word_chars, 0) + 1

        return word_freq

    def _select_best_pair(self, pairs: Dict[Tuple[str, str], int], word_freq: Dict[str, int]) -> Optional[Tuple[str, str]]:
        """Legjobb BPE pár kiválasztása entrópia alapján"""
        if not pairs:
            return None

        # Gyakoriság alapú kiválasztás
        max_freq = max(pairs.values())
        best_pairs = [pair for pair, freq in pairs.items() if freq == max_freq]

        # Ha több egyforma gyakoriságú van, válasszuk a rövidebbet
        return min(best_pairs, key=lambda x: len(x[0] + x[1]))

    def _get_word_frequencies(self, texts: List[str]) -> Dict[str, int]:
        """Szavak gyakoriságának megszámolása"""
        word_freq = {}
        for text in texts:
            words = text.lower().split()
            for word in words:
                word_chars = ' '.join(word) + ' </w>'
                word_freq[word_chars] = word_freq.get(word_chars, 0) + 1
        return word_freq

    def _get_pairs_frequencies(self, word_freq: Dict[str, int]) -> Dict[Tuple[str, str], int]:
        """Karakter párok gyakoriságának számolása"""
        pairs = {}
        for word, freq in word_freq.items():
            symbols = word.split()
            for i in range(len(symbols) - 1):
                pair = (symbols[i], symbols[i + 1])
                pairs[pair] = pairs.get(pair, 0) + freq
        return pairs

    def _merge_pair(self, pair: Tuple[str, str], word_freq: Dict[str, int]):
        """Pár összeolvasztása a vocabulárban"""
        new_word_freq = {}
        bigram = ' '.join(pair)
        replacement = ''.join(pair)

        for word in word_freq:
            new_word = word.replace(bigram, replacement)
            new_word_freq[new_word] = word_freq[word]

        word_freq.clear()
        word_freq.update(new_word_freq)

    def encode(self, text: str, add_special_tokens: bool = True) -> List[int]:
        """GPT-4 szintű tokenizálás contextual awareness-szel"""
        if not text.strip():
            return [self.special_tokens['<|pad|>']]

        tokens = []

        if add_special_tokens:
            tokens.append(self.special_tokens['<|startoftext|>'])

        # Nyelvfelismerés és domain detektálás
        detected_lang = self._detect_language(text)
        if detected_lang:
            tokens.append(self.language_tokens.get(detected_lang, self.special_tokens['<|unk|>']))

        # Fejlett tokenizálás BPE merge-ekkel
        words = self._advanced_tokenize(text)

        for word in words:
            word_tokens = self._encode_word(word)
            tokens.extend(word_tokens)

        if add_special_tokens:
            tokens.append(self.special_tokens['<|endoftext|>'])

        return tokens

    def _detect_language(self, text: str) -> Optional[str]:
        """Egyszerű nyelvfelismerés"""
        hungarian_words = ['és', 'a', 'az', 'hogy', 'de', 'ha', 'nem', 'van', 'egy', 'ez']
        english_words = ['the', 'and', 'or', 'but', 'if', 'not', 'is', 'are', 'a', 'an']

        text_lower = text.lower()
        hungarian_count = sum(1 for word in hungarian_words if word in text_lower)
        english_count = sum(1 for word in english_words if word in text_lower)

        if hungarian_count > english_count:
            return '<|hungarian|>'
        elif english_count > 0:
            return '<|english|>'
        return None

    def _advanced_tokenize(self, text: str) -> List[str]:
        """Fejlett tokenizálás különböző content típusokhoz"""
        # Kód blokkok felismerése
        if '```' in text or 'def ' in text or 'function ' in text:
            return self._tokenize_code(text)

        # Matematikai kifejezések
        if re.search(r'\\[a-zA-Z]+|\\[{}$]|\$.*?\$', text):
            return self._tokenize_math(text)

        # Normál szöveg tokenizálás
        return re.findall(r'\w+|[^\w\s]', text)

    def _tokenize_code(self, text: str) -> List[str]:
        """Kód tokenizálás"""
        # Speciális kód tokenek
        pattern = r'(def|class|if|else|for|while|import|from|return|"[^"]*"|\'[^\']*\'|[a-zA-Z_]\w*|[+\-*/=<>!&|]+|\d+|[^\w\s])'
        matches = re.findall(pattern, text)

        return matches

    def _tokenize_math(self, text: str) -> List[str]:
        """Matematikai tokenizálás"""
        # LaTeX parancsok és matematikai szimbólumok
        pattern = r'(\\[a-zA-Z]+|\\[{}$]|\$[^$]*\$|[a-zA-Z_]\w*|\d+|[+\-*/=<>^_{}()[\]]|[^\w\s])'
        matches = re.findall(pattern, text)

        return matches

    def _encode_word(self, word: str) -> List[int]:
        """Szó tokenizálása BPE algoritmussal"""
        if word in self.vocab:
            return [self.vocab[word]]

        # BPE merge alkalmazása
        word_chars = list(word)

        # Alkalmazzuk a merge szabályokat
        for merge_pair in self.bpe_merges:
            if len(word_chars) < 2:
                break

            i = 0
            while i < len(word_chars) - 1:
                if (word_chars[i], word_chars[i + 1]) == merge_pair:
                    merged = word_chars[i] + word_chars[i + 1]
                    word_chars = word_chars[:i] + [merged] + word_chars[i + 2:]
                else:
                    i += 1

        # Token ID-k visszaadása
        tokens = []
        for char_or_subword in word_chars:
            if char_or_subword in self.vocab:
                tokens.append(self.vocab[char_or_subword])
            else:
                # Byte-level fallback
                for byte_val in char_or_subword.encode('utf-8', errors='ignore'):
                    byte_token = chr(byte_val) if byte_val < 128 else f"<{byte_val}>"
                    tokens.append(self.vocab.get(byte_token, self.special_tokens['<|unk|>']))

        return tokens

    def decode(self, token_ids: List[int], skip_special_tokens: bool = True) -> str:
        """GPT-4 szintű dekodolás"""
        if not token_ids:
            return ""

        tokens = []
        for token_id in token_ids:
            if token_id in self.reverse_vocab:
                token = self.reverse_vocab[token_id]

                if skip_special_tokens and token.startswith('<|') and token.endswith('|>'):
                    continue

                tokens.append(token)

        # BPE merge visszafordítás és tisztítás
        text = ''.join(tokens)
        text = text.replace('</w>', ' ')
        text = re.sub(r'<\d+>', lambda m: chr(int(m.group()[1:-1])), text)

        return text.strip()

    def get_vocab_info(self) -> Dict[str, any]:
        """Vocabulár információk"""
        return {
            'vocab_size': len(self.vocab),
            'special_tokens': len(self.special_tokens),
            'bpe_merges': len(self.bpe_merges),
            'signature': '🔑 Sándor Kollár - Advanced GPT-4 Level Tokenizer'
        }


