class NeuralODEBlock(nn.Module):
    """Neural ODE block using torchdiffeq"""
    def __init__(self, ode_func, integration_time_points):
        super().__init__()
        self.ode_func = ode_func
        self.integration_time_points = torch.tensor(integration_time_points).float()

    def forward(self, x):
        if TORCHDIFFEQ_AVAILABLE:
            out = torchdiffeq.odeint(self.ode_func, x, self.integration_time_points, rtol=1e-3, atol=1e-4)
            return out[-1]
        else:
            # Fallback: simple residual connection
            return x + self.ode_func(0, x)


class AdvancedMultiHeadAttention:
    def __init__(self, d_model: int, num_heads: int, use_hnn: bool = False, 
                 use_rope: bool = True, use_flash_attention: bool = True):
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.use_hnn = use_hnn
        self.use_rope = use_rope
        self.use_flash_attention = use_flash_attention

        # GPT-4 szintű weight matrices NTK-inspired scaling-gel
        std_dev = np.sqrt(2.0 / d_model)
        self.W_q = np.random.normal(0, std_dev, (d_model, d_model))
        self.W_k = np.random.normal(0, std_dev, (d_model, d_model))
        self.W_v = np.random.normal(0, std_dev, (d_model, d_model))
        self.W_o = np.random.normal(0, std_dev, (d_model, d_model))

        # Fejlett KV-Cache több rétegű
        self.kv_cache = None
        self.attention_cache = {}

        # Dropout és layer normalization paraméterek
        self.dropout_prob = 0.1
        self.attention_dropout_prob = 0.1

        print(f"🧠 AdvancedMultiHeadAttention: {num_heads} heads, RoPE: {use_rope}, Flash: {use_flash_attention}")

    def forward(self, x: np.ndarray, rope_embeddings: np.ndarray = None, 
                use_cache: bool = False, attention_mask: np.ndarray = None) -> np.ndarray:
        batch_size, seq_len, d_model = x.shape

        # Linear transformations
        Q = np.dot(x, self.W_q)
        K = np.dot(x, self.W_k)
        V = np.dot(x, self.W_v)

        # RoPE alkalmazása
        if self.use_rope and rope_embeddings is not None:
            Q = self._apply_rope_to_qk(Q, rope_embeddings)
            K = self._apply_rope_to_qk(K, rope_embeddings)

        # KV-Cache usage - fejlettebb cache kezelés
        if use_cache and self.kv_cache is not None:
            K = np.concatenate([self.kv_cache['K'], K[:, -1:, :]], axis=1)
            V = np.concatenate([self.kv_cache['V'], V[:, -1:, :]], axis=1)
            self.kv_cache = {'K': K, 'V': V}
        elif use_cache:
            self.kv_cache = {'K': K, 'V': V}

        # Reshape for multi-head attention
        Q = Q.reshape(batch_size, seq_len, self.num_heads, self.d_k).transpose(0, 2, 1, 3)
        K = K.reshape(batch_size, K.shape[1], self.num_heads, self.d_k).transpose(0, 2, 1, 3)
        V = V.reshape(batch_size, V.shape[1], self.num_heads, self.d_k).transpose(0, 2, 1, 3)

        # Flash Attention inspirált implementáció
        if self.use_flash_attention:
            context = self._flash_attention(Q, K, V, attention_mask)
        else:
            context = self._standard_attention(Q, K, V, attention_mask)

        # Concatenate heads
        context = context.transpose(0, 2, 1, 3).reshape(batch_size, seq_len, d_model)

        # Final linear transformation
        output = np.dot(context, self.W_o)

        # Dropout alkalmazása
        if np.random.random() < self.dropout_prob:
            output *= (1.0 - self.dropout_prob)

        return output

    def _apply_rope_to_qk(self, qk: np.ndarray, rope_embeddings: np.ndarray) -> np.ndarray:
        """RoPE alkalmazása Q és K mátrixokra"""
        batch_size, seq_len, d_model = qk.shape
        rope_qk = np.zeros_like(qk)

        for b in range(batch_size):
            for s in range(min(seq_len, rope_embeddings.shape[0])):
                for i in range(0, d_model, 2):
                    if i + 1 < d_model:
                        cos_val = rope_embeddings[s, i]
                        sin_val = rope_embeddings[s, i + 1]

                        q1, q2 = qk[b, s, i], qk[b, s, i + 1]

                        rope_qk[b, s, i] = q1 * cos_val - q2 * sin_val
                        rope_qk[b, s, i + 1] = q1 * sin_val + q2 * cos_val

        return rope_qk

    def _flash_attention(self, Q: np.ndarray, K: np.ndarray, V: np.ndarray, 
                        attention_mask: np.ndarray = None) -> np.ndarray:
        """Flash Attention inspirált memória-hatékony implementáció"""
        batch_size, num_heads, seq_len_q, d_k = Q.shape
        seq_len_k = K.shape[2]

        # Chunked attention blokk méret
        block_size = min(512, seq_len_q)

        output = np.zeros_like(Q)

        for b in range(batch_size):
            for h in range(num_heads):
                # Blokkok szerint dolgozunk memória hatékonyság miatt
                for i in range(0, seq_len_q, block_size):
                    end_i = min(i + block_size, seq_len_q)

                    Q_block = Q[b, h, i:end_i, :]

                    # Attention scores számítása
                    scores = np.matmul(Q_block, K[b, h].T) / np.sqrt(d_k)

                    # Causal mask alkalmazása
                    if attention_mask is None:
                        mask = np.triu(np.ones((end_i - i, seq_len_k)), k=seq_len_k - (end_i - i) + 1)
                        scores = scores - mask * 1e9

                    # Numerically stable softmax
                    exp_scores = np.exp(scores - np.max(scores, axis=-1, keepdims=True))
                    attention_weights = exp_scores / np.sum(exp_scores, axis=-1, keepdims=True)

                    # Attention dropout
                    if np.random.random() < self.attention_dropout_prob:
                        attention_weights *= (1.0 - self.attention_dropout_prob)

                    # Context számítása
                    output[b, h, i:end_i, :] = np.matmul(attention_weights, V[b, h])

        return output

    def _standard_attention(self, Q: np.ndarray, K: np.ndarray, V: np.ndarray, 
                           attention_mask: np.ndarray = None) -> np.ndarray:
        """Standard attention implementáció"""
        # Scaled dot-product attention
        scores = np.matmul(Q, K.transpose(0, 1, 3, 2)) / np.sqrt(self.d_k)

        # Apply causal mask
        if attention_mask is None:
            seq_len_q, seq_len_k = Q.shape[2], K.shape[2]
            mask = np.triu(np.ones((seq_len_q, seq_len_k)), k=1)
            scores = scores - mask * 1e9

        attention_weights = self.softmax(scores)
        context = np.matmul(attention_weights, V)

        return context

    def clear_cache(self):
        """Clear KV cache"""
        self.kv_cache = None

    def softmax(self, x: np.ndarray) -> np.ndarray:
        exp_x = np.exp(x - np.max(x, axis=-1, keepdims=True))
        return exp_x / np.sum(exp_x, axis=-1, keepdims=True)


class AdvancedFeedForward:
    """Advanced FeedForward with HNN support"""
    def __init__(self, d_model: int, d_ff: int, use_hnn: bool = False):
        self.use_hnn = use_hnn
        self.d_model = d_model
        self.d_ff = d_ff

        if self.use_hnn and GEOOPT_AVAILABLE:
            # Initialize hyperbolic layers
            self.hnn1 = HyperbolicMLP(d_model, d_ff)
            self.hnn2 = HyperbolicMLP(d_ff, d_model)
        else:
            # NTK-inspired initialization
            std_dev = np.sqrt(2.0 / d_model)
            self.W1 = np.random.normal(0, std_dev, (d_model, d_ff))
            self.b1 = np.zeros(d_ff)
            self.W2 = np.random.normal(0, std_dev, (d_ff, d_model))
            self.b2 = np.zeros(d_model)

    def forward(self, x: np.ndarray) -> np.ndarray:
        if self.use_hnn and GEOOPT_AVAILABLE:
            x_torch = torch.from_numpy(x).float()
            hidden = self.hnn1(x_torch)
            output = self.hnn2(hidden)
            return output.detach().numpy()
        else:
            hidden = np.dot(x, self.W1) + self.b1
            hidden = self.gelu(hidden)
            output = np.dot(hidden, self.W2) + self.b2
            return output

    def gelu(self, x: np.ndarray) -> np.ndarray:
        return 0.5 * x * (1 + np.tanh(np.sqrt(2 / np.pi) * (x + 0.044715 * x**3)))


class AdvancedMixtureOfExperts:
    """Advanced Mixture of Experts implementation"""
    def __init__(self, d_model: int, d_ff: int, num_experts: int = 8, top_k: int = 2):
        self.d_model = d_model
        self.d_ff = d_ff
        self.num_experts = num_experts
        self.top_k = top_k

        # Create expert networks
        self.experts = []
        for _ in range(num_experts):
            std_dev = np.sqrt(2.0 / d_model)
            expert = {
                'W1': np.random.normal(0, std_dev, (d_model, d_ff)),
                'b1': np.zeros(d_ff),
                'W2': np.random.normal(0, std_dev, (d_ff, d_model)),
                'b2': np.zeros(d_model)
            }
            self.experts.append(expert)

        # Gate network
        self.gate_W = np.random.normal(0, np.sqrt(1.0 / d_model), (d_model, num_experts))
        self.gate_b = np.zeros(num_experts)

    def __call__(self, x_torch):
        """Make the class callable for compatibility"""
        x_numpy = x_torch.detach().numpy() if isinstance(x_torch, torch.Tensor) else x_torch
        output, aux_loss = self.forward(x_numpy)
        if isinstance(x_torch, torch.Tensor):
            return torch.from_numpy(output).float(), aux_loss
        return output, aux_loss

    def forward(self, x: np.ndarray) -> Tuple[np.ndarray, float]:
        batch_size, seq_len, d_model = x.shape
        x_flat = x.reshape(-1, d_model)

        # Compute gate scores
        gate_logits = np.dot(x_flat, self.gate_W) + self.gate_b
        gate_probs = self.softmax(gate_logits)

        # Get top-k experts
        top_k_indices = np.argpartition(gate_probs, -self.top_k, axis=1)[:, -self.top_k:]
        top_k_probs = np.take_along_axis(gate_probs, top_k_indices, axis=1)

        # Normalize top-k probabilities
        top_k_probs = top_k_probs / np.sum(top_k_probs, axis=1, keepdims=True)

        # Process through experts
        output = np.zeros_like(x_flat)
        aux_loss = 0.0

        for i in range(x_flat.shape[0]):
            expert_outputs = []
            for k in range(self.top_k):
                expert_idx = top_k_indices[i, k]
                expert = self.experts[expert_idx]

                # Forward through expert
                hidden = np.dot(x_flat[i], expert['W1']) + expert['b1']
                hidden = self.gelu(hidden)
                expert_output = np.dot(hidden, expert['W2']) + expert['b2']

                expert_outputs.append(expert_output * top_k_probs[i, k])

            output[i] = np.sum(expert_outputs, axis=0)

            # Auxiliary loss for load balancing
            aux_loss += np.mean(gate_probs[i] * np.sum(gate_probs, axis=0))

        output = output.reshape(batch_size, seq_len, d_model)
        return output, aux_loss / (batch_size * seq_len)

    def gelu(self, x: np.ndarray) -> np.ndarray:
        return 0.5 * x * (1 + np.tanh(np.sqrt(2 / np.pi) * (x + 0.044715 * x**3)))

    def softmax(self, x: np.ndarray) -> np.ndarray:
        exp_x = np.exp(x - np.max(x, axis=-1, keepdims=True))
        return exp_x / np.sum(exp_x, axis=-1, keepdims=True)


class AdvancedTransformerBlock:
    def __init__(self, d_model: int, num_heads: int, d_ff: int, use_moe: bool = False, 
                 use_hnn: bool = False, use_rope: bool = True, use_flash_attention: bool = True,
                 num_experts: int = 8, top_k: int = 2, layer_id: int = 0):
        self.layer_id = layer_id
        self.d_model = d_model

        # Fejlett attention mechanizmus
        self.attention = AdvancedMultiHeadAttention(
            d_model, num_heads, 
            use_hnn=use_hnn, 
            use_rope=use_rope, 
            use_flash_attention=use_flash_attention
        )

        self.use_moe = use_moe
        self.use_hnn = use_hnn

        # Mixture of Experts vagy standard feed forward
        if self.use_moe:
            self.moe_feed_forward = AdvancedMixtureOfExperts(d_model, d_ff, num_experts, top_k)
        else:
            self.feed_forward = AdvancedFeedForward(d_model, d_ff, use_hnn=use_hnn)

        # Layer normalization parameters
        self.norm1_gamma = np.ones(d_model)
        self.norm1_beta = np.zeros(d_model)
        self.norm2_gamma = np.ones(d_model)
        self.norm2_beta = np.zeros(d_model)
        self.eps = 1e-6

        # Dropout és residual scaling
        self.dropout_prob = 0.1
        self.residual_scaling = 1.0 / np.sqrt(2 * (layer_id + 1))  # Layer-wise scaling

        print(f"  📦 Layer {layer_id}: MoE={use_moe}, HNN={use_hnn}, RoPE={use_rope}")

    def rms_norm(self, x: np.ndarray, weight: np.ndarray) -> np.ndarray:
        """RMSNorm - modern normalizáció GPT-4 stílusban"""
        variance = np.mean(x ** 2, axis=-1, keepdims=True)
        x = x / np.sqrt(variance + self.eps)
        return x * weight

    def layer_norm(self, x: np.ndarray, gamma: np.ndarray, beta: np.ndarray) -> np.ndarray:
        mean = np.mean(x, axis=-1, keepdims=True)
        var = np.var(x, axis=-1, keepdims=True)
        return gamma * (x - mean) / np.sqrt(var + self.eps) + beta

    def forward(self, x: np.ndarray, rope_embeddings: np.ndarray = None, 
                use_cache: bool = False) -> np.ndarray:
        # Pre-norm architecture
        norm_x = self.layer_norm(x, self.norm1_gamma, self.norm1_beta)
        attn_output = self.attention.forward(norm_x, rope_embeddings, use_cache=use_cache)
        x = x + attn_output * self.residual_scaling

        norm_x = self.layer_norm(x, self.norm2_gamma, self.norm2_beta)

        if self.use_moe:
            ff_output, moe_aux_loss = self.moe_feed_forward.forward(norm_x)
        else:
            ff_output = self.feed_forward.forward(norm_x)

        x = x + ff_output * self.residual_scaling

        return x


